/*
 * A170632  Number of reduced words of length n in Coxeter group on 47
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^48 = I.
 * https://oeis.org/A170632
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 5, u64 n <= 11, u128 n <= 14,
 *            big any n
 * Helpers:   alloc_seq_array, free_seq_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Sequence A170632: number of reduced words of length n
 *  in the Coxeter group generated by 47 involutions with
 *  relations (S_i)^2 = (S_i S_j)^48 = I.
 *
 *  The generating function satisfies
 *      (t^48 + 2*t^47 + 2*t^46 + ... + 2*t + 1) / (
 *          1035*t^48 - 45*t^47 - ... - 45*t - 1 )
 *  which leads to the linear recurrence
 *
 *      a(n) = 45*a(n-1) + 45*a(n-2) + ... + 45*a(n-47)
 *             - 1035*a(n-48) + p_n   (n ≥ 1),
 *  where p_n = 1 for n = 0 or 48, 2 for 1 ≤ n ≤ 47, and 0 otherwise.
 *
 *  The function below memoises the values in a static array so that
 *  calls may be in any order.
 */

#include <stdlib.h>
#include <string.h>
#include "../utils/alloc_seq_array.h"
#include "../utils/free_seq_array.h"

static seq_t *seq_cache = NULL;   /* cached values a(0), a(1), … */
static size_t cache_size = 0;     /* allocated size of seq_cache      */
static idx_t  cache_count = 0;    /* number of computed terms        */

seq_t a(idx_t n)
{
    /* Grow the cache so that it holds indices up to n.  */
    if ((size_t)n + 1 > cache_size) {
        size_t new_size = cache_size ? cache_size * 2 : 64;
        if (new_size <= (size_t)n + 1)
            new_size = (size_t)n + 1;

        seq_t *tmp = alloc_seq_array(new_size);
        if (!tmp) abort();                 /* out of memory */

        if (seq_cache) {
            memcpy(tmp, seq_cache, cache_size * sizeof(seq_t));
            free_seq_array(seq_cache);
        }
        seq_cache = tmp;
        cache_size = new_size;
    }

    /* Compute any missing terms up to n.  */
    for (size_t i = cache_count; i <= (size_t)n; ++i) {
        seq_t val;
        /* The particular term from the numerator of the GF.  */
        if (i == 0 || i == 48)
            val = (seq_t)1;
        else if (i <= 47)
            val = (seq_t)2;
        else
            val = (seq_t)0;

        /* Add Σ 45·a(i-j) for j = 1 … min(47,i).  */
        size_t maxj = i < 47 ? i : 47;
        for (size_t j = 1; j <= maxj; ++j)
            val += seq_cache[i - j] * (seq_t)45;

        /* Subtract 1035·a(i-48) if i ≥ 48.  */
        if (i >= 48)
            val -= seq_cache[i - 48] * (seq_t)1035;

        seq_cache[i] = val;
    }

    cache_count = n + 1;
    return seq_cache[(size_t)n];
}
